import { NextRequest, NextResponse } from "next/server";
import { createClient } from "~/utils/supabase/server";
import internalError from "~/utils/internalErrorSsr";

export const GET = async (request: NextRequest): Promise<NextResponse> => {
  const params = request.nextUrl.searchParams;
  const token = params.get("t");
  const url = params.get("url");
  try {
    if (typeof token !== "string") throw new Error("Please provide a token");
    if (typeof url !== "string") throw new Error("Please provide a single URL");
    if (
      url.indexOf("://") >= 0 &&
      !url.startsWith(request.nextUrl.origin + "/")
    )
      throw new Error("Absolute URLs should be within the application");

    const client = await createClient();
    const result = await client.rpc("get_secret_token", {
      token,
    });
    if (result.error) {
      internalError({ error: result.error, type: "get-secret-token" });
      throw new Error("Could not connect to DiscourseGraphs");
    }
    if (result.data == null) {
      internalError({ error: "missing token", type: "get-secret-token" });
      throw new Error("Could not retrieve information, please try again.");
    }
    if (typeof result.data !== "string") {
      internalError({
        error: "payload-not-string",
        type: "get-secret-token",
      });
      throw new Error(
        "DiscourseGraphs configuration error, the team has been warned",
      );
    }
    const data = JSON.parse(result.data) as {
      access_token: string;
      refresh_token: string;
    };
    if (
      !data ||
      typeof data !== "object" ||
      !data.access_token ||
      !data.refresh_token
    ) {
      internalError({ error: "misshaped-payload", type: "get-secret-token" });
      throw new Error(
        "DiscourseGraphs configuration error, the team has been warned",
      );
    }
    const response = await client.auth.setSession(data);
    if (response.error) {
      throw response.error;
    }
  } catch (error) {
    return NextResponse.redirect(
      new URL(
        "/auth/error?error=" +
          encodeURIComponent(
            error instanceof Error
              ? error.message
              : "Unkown error while logging you in.",
          ),
        request.nextUrl,
      ),
    );
  }
  return NextResponse.redirect(
    new URL(url, url.startsWith("http") ? undefined : request.nextUrl),
  );
};
CREATE TABLE IF NOT EXISTS public.secret_token (
    id varchar PRIMARY KEY DEFAULT encode(extensions.gen_random_bytes(12), 'base64'),
    creator UUID NOT NULL DEFAULT auth.uid(),
    payload JSONB NOT NULL,
    expiry_date timestamp without time zone,
    one_time_use boolean DEFAULT true
);

CREATE INDEX IF NOT EXISTS secret_token_expiry_idx ON public.secret_token (expiry_date) WHERE expiry_date IS NOT null;

CREATE OR REPLACE FUNCTION public.create_secret_token(v_payload JSONB, v_one_time_use BOOLEAN DEFAULT true, expiry_interval INTERVAL DEFAULT '30d') RETURNS VARCHAR
SECURITY DEFINER
SET search_path = ''
LANGUAGE sql AS $$
    INSERT INTO public.secret_token (payload, expiry_date, one_time_use) VALUES (v_payload, now()+expiry_interval, v_one_time_use) RETURNING id;
$$;

CREATE OR REPLACE FUNCTION public.get_secret_token(token VARCHAR) RETURNS JSONB
SECURITY DEFINER
SET search_path = ''
LANGUAGE plpgsql AS $$
DECLARE
v_payload JSONB;
v_one_time_use BOOLEAN;
BEGIN
    DELETE FROM public.secret_token WHERE expiry_date < now();
    DELETE FROM public.secret_token WHERE id=token AND one_time_use = true RETURNING payload INTO v_payload;
    IF v_payload IS NULL THEN
        SELECT payload INTO v_payload FROM public.secret_token WHERE id=token;
    END IF;
    RETURN v_payload;
END;
$$;

